param([switch]$Background); $d=Split-Path -Parent $MyInvocation.MyCommand.Path; $x=Join-Path $d "target\release\zorya.exe"; $o=Join-Path $d "zorya_node.log"; $e=Join-Path $d "zorya_err.log"; Get-Process zorya -ErrorAction SilentlyContinue | Stop-Process -Force; if($Background){ Start-Process -FilePath $x -WorkingDirectory $d -RedirectStandardOutput $o -RedirectStandardError $e -WindowStyle Hidden; Write-Host "[Zorya] Iniciado em background!" -ForegroundColor Green; exit 0 }; & $x
